<template><view class="exchange"><view class="card"><text class="heading">积分兑换</text><view>可用 {{points}} 积分</view><text class="hint">兑换后仍需确认收货地址并提交订单；兑换商品不叠加优惠券，不赠送消费积分。需要配送时运费按商城配送规则另付（结算页会显示运费金额）。</text></view><view v-if="error" class="card">{{error}}</view><view class="card" v-for="p in products" :key="p.id"><image :src="asset(p.image)" mode="aspectFill"/><view>{{p.name}} {{p.spec}}</view><view>{{p.points_cost}} 积分 / 件 · 库存 {{p.stock}} 件</view><button class="ui-button" :disabled="points<p.points_cost||p.stock<1" @click="choose(p)">{{points<p.points_cost?'积分不足':'兑换这件商品'}}</button></view><view v-if="!products.length&&!error" class="card">当前没有开放兑换的商品。</view></view></template>
<script>
import {refreshOnTick} from '../services/panel-refresh'
import {request,asset,go} from '../services/shop'
export default {mixins:[refreshOnTick()],data(){return{products:[],points:0,error:''}},mounted(){this.load()},methods:{asset,async load(){try{const [p,a]=await Promise.all([request('/point-exchange'),request('/points')]);this.products=p;this.points=a.available;this.error=''}catch(e){this.error=e.message}},choose(p){const uid=uni.getStorageSync('shop-owner');uni.setStorageSync('shop-cart-'+uid+'-checkout',{channel:'C',exchange:true,items:[{id:p.id,quantity:1}],requestKey:'exchange_'+Date.now()+'_'+Math.random().toString(36).slice(2)});go('checkout')}}}
</script><style scoped>
@import '../styles/component-base.css';
.exchange{padding:16px;font-size:16px}.card{background:var(--shop-surface, #fdfeff);padding:16px;border-radius:12px;margin-bottom:14px;line-height:1.9}.heading{font-size:20px;font-weight:bold}.hint{font-size:14px;color:var(--shop-ink, #28546c)}image{width:110px;height:110px;border-radius:8px}button{background:var(--shop-accent, #c7e8f5);color:var(--shop-ink, #28546c);font-size:16px;margin-top:12px}</style>
